find:
if raw > MAX_INSTALLATION_ID {
    return Err(ScmError::InvalidInput(format!(
        "installation id {raw} exceeds the maximum {MAX_INSTALLATION_ID} \
         (i64::MAX, the signed SQLite INTEGER bound)"
    )));
}

replace:
if raw <= MAX_INSTALLATION_ID {
    return Err(ScmError::InvalidInput(format!(
        "installation id {raw} exceeds the maximum {MAX_INSTALLATION_ID} \
         (i64::MAX, the signed SQLite INTEGER bound)"
    )));
}
